from urllib.parse import urlparse

from flask import Flask, abort, jsonify, redirect


SHORT_URLS = {
    "abc123": "https://example.com/articles/intro",
}

# Only http and https targets may be redirected to. Anything else
# (javascript:, data:, ftp:, ...) must never be used as a redirect target.
_ALLOWED_SCHEMES = ("http", "https")


def _safe_target(target) -> bool:
    """Return True if *target* is an absolute http(s) URL."""
    if not isinstance(target, str) or not target:
        return False
    scheme = urlparse(target).scheme.lower()
    return scheme in _ALLOWED_SCHEMES


def create_app():
    app = Flask(__name__)

    @app.get("/r/<code>")
    def resolve(code):
        try:
            target = SHORT_URLS[code]
        except KeyError:
            return jsonify(error="unknown short code"), 404

        if not _safe_target(target):
            abort(400, description="unsafe redirect target")

        # 301: permanent redirect (cacheable by browsers and search engines)
        return redirect(target, code=301)

    return app


app = create_app()

import pytest

from app import create_app


@pytest.fixture()
def client():
    return create_app().test_client()


def test_known_code_redirects(client):
    r = client.get("/r/abc123")
    assert r.status_code == 301
    assert r.headers["Location"] == "https://example.com/articles/intro"


def test_unknown_code_returns_json_404(client):
    r = client.get("/r/does-not-exist")
    assert r.status_code == 404
    assert r.get_json() == {"error": "unknown short code"}


def test_unsafe_scheme_is_rejected(client, monkeypatch):
    from app import SHORT_URLS

    monkeypatch.setitem(SHORT_URLS, "evil", "javascript:alert(1)")
    r = client.get("/r/evil")
    assert r.status_code == 400


def test_protocol_relative_url_is_rejected(client, monkeypatch):
    from app import SHORT_URLS

    monkeypatch.setitem(SHORT_URLS, "pr", "//evil.example/steal")
    r = client.get("/r/pr")
    assert r.status_code == 400


def test_http_targets_are_allowed(client, monkeypatch):
    from app import SHORT_URLS

    monkeypatch.setitem(SHORT_URLS, "plain", "http://example.com/page")
    r = client.get("/r/plain")
    assert r.status_code == 301
    assert r.headers["Location"] == "http://example.com/page"
